package com.medical.ui.panels;
import com.medical.ui.dialogs.PatientDialog;import com.medical.ui.models.*;import com.medical.ui.utils.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.Arrays;
public class PatientPanel extends JPanel{private final ApiClient api;private final PatientTableModel model=new PatientTableModel();private final JTable table=new JTable(model);private final JLabel status;private final JComboBox<String>type=new JComboBox<>(new String[]{"Code","Nom"});private final JTextField search=new JTextField(20);public PatientPanel(ApiClient a,JLabel s){api=a;status=s;setLayout(new BorderLayout(12,12));setBorder(new EmptyBorder(4,4,4,4));add(top(),BorderLayout.NORTH);UiStyle.table(table);table.setAutoCreateRowSorter(true);RowActionCell.install(table,5,this::editRow,this::deleteRow);add(UiStyle.card(new JScrollPane(table)),BorderLayout.CENTER);refresh();}
private JPanel top(){JPanel root=new JPanel(new BorderLayout(15,8));JPanel title=new JPanel();title.setLayout(new BoxLayout(title,BoxLayout.Y_AXIS));title.add(UiStyle.title("Patients"));title.add(UiStyle.muted("Recherche par code exact ou nom partiel"));JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));JButton a=new JButton("＋  Ajouter"),r=new JButton("↻  Actualiser");UiStyle.primaryButton(a);UiStyle.secondaryButton(r);a.addActionListener(e->add());r.addActionListener(e->refresh());actions.add(a);actions.add(r);JPanel searchBar=new JPanel(new BorderLayout(8,0));searchBar.setBorder(new EmptyBorder(8,0,0,0));type.setPreferredSize(new Dimension(90,34));search.setPreferredSize(new Dimension(250,34));JButton go=new JButton("Rechercher"),clear=new JButton("Effacer");UiStyle.secondaryButton(go);UiStyle.secondaryButton(clear);go.addActionListener(e->search());clear.addActionListener(e->{search.setText("");refresh();});searchBar.add(new JLabel("Recherche"),BorderLayout.WEST);searchBar.add(type,BorderLayout.CENTER);JPanel field=new JPanel(new BorderLayout(6,0));field.add(search,BorderLayout.CENTER);field.add(go,BorderLayout.EAST);field.add(clear,BorderLayout.WEST);searchBar.add(field,BorderLayout.EAST);JPanel north=new JPanel(new BorderLayout());north.add(title,BorderLayout.WEST);north.add(actions,BorderLayout.EAST);root.add(north,BorderLayout.NORTH);root.add(searchBar,BorderLayout.SOUTH);return root;}
private void refresh(){load("/api/patients");}private void search(){if(search.getText().isBlank()){refresh();return;}String q=type.getSelectedItem().toString().equals("Code")?"code":"nom";load("/api/patients/search?type="+q+"&value="+api.encode(search.getText().trim()));}private void load(String path){new SwingWorker<Patient[],Void>(){protected Patient[]doInBackground()throws Exception{return api.get(path,Patient[].class);}protected void done(){try{model.setData(Arrays.asList(get()));status.setText("  "+model.getRowCount()+" patient(s) affiché(s)");}catch(Exception e){error(e);}}}.execute();}
private void add(){PatientDialog d=new PatientDialog(SwingUtilities.getWindowAncestor(this),null);d.setVisible(true);if(!d.isOk())return;run(()->api.post("/api/patients",new Patient(d.code(),d.nom(),d.prenom(),d.sexe(),d.adresse()),Patient.class));}private void editRow(int row){Patient o=model.getAt(row);PatientDialog d=new PatientDialog(SwingUtilities.getWindowAncestor(this),o);d.setVisible(true);if(!d.isOk())return;run(()->api.put("/api/patients/"+api.encode(o.codePat()),new Patient(d.code(),d.nom(),d.prenom(),d.sexe(),d.adresse()),Patient.class));}private void deleteRow(int row){Patient x=model.getAt(row);if(JOptionPane.showConfirmDialog(this,"Supprimer le patient « "+x.codePat()+" » ?","Confirmation",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{api.delete("/api/patients/"+api.encode(x.codePat()));return null;}protected void done(){try{get();refresh();status.setText("  Patient supprimé");}catch(Exception e){error(e);}}}.execute();}private interface Task{Object run()throws Exception;}private void run(Task t){new SwingWorker<Object,Void>(){protected Object doInBackground()throws Exception{return t.run();}protected void done(){try{get();refresh();status.setText("  Opération réalisée avec succès");}catch(Exception e){error(e);}}}.execute();}private void error(Exception e){Throwable x=e instanceof java.util.concurrent.ExecutionException&&e.getCause()!=null?e.getCause():e;status.setText("  Erreur : "+x.getMessage());JOptionPane.showMessageDialog(this,x.getMessage(),"Erreur",JOptionPane.ERROR_MESSAGE);}}
